package com.sivion.api.crm.repo; import com.sivion.api.crm.domain.Customer; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface CustomerRepository extends JpaRepository<Customer,Long>{List<Customer> findByTenantIdOrderByNameAsc(Long tenantId); List<Customer> findByTenantIdAndNameContainingIgnoreCaseOrderByNameAsc(Long tenantId,String name); Optional<Customer> findByTenantIdAndCode(Long tenantId,String code);}